844:     requires
845:         #[trigger] spec.entails(not(p)),
846:     ensures
847:         !spec.entails(p),
848: {
849:     assume(exists|ex| spec.satisfied_by(ex));
850:     let ex = choose|ex| spec.satisfied_by(ex);
851:     assert(spec.satisfied_by(ex));
852:     assert(spec.implies(not(p)).satisfied_by(ex));
853:     assert(!p.satisfied_by(ex));
854:     assert(!spec.implies(p).satisfied_by(ex));
